#include "audio/Audio.h"
#include <fstream>
namespace forge::audio {template<class T>bool rd(std::ifstream&f,T&v){f.read(reinterpret_cast<char*>(&v),sizeof(T));return !!f;}bool AudioEngine::loadWav(const std::filesystem::path&p,WavInfo&o,std::string&e){std::ifstream f(p,std::ios::binary);if(!f){e="WAV file not found";return false;}char riff[4],wave[4];uint32_t size;f.read(riff,4);rd(f,size);f.read(wave,4);if(std::string(riff,4)!="RIFF"||std::string(wave,4)!="WAVE"){e="Unsupported WAV header";return false;}char id[4];while(f.read(id,4)){uint32_t n=0;rd(f,n);if(std::string(id,4)=="fmt "){uint16_t fmt=0;rd(f,fmt);rd(f,o.channels);rd(f,o.sampleRate);uint32_t byteRate;rd(f,byteRate);uint16_t block;rd(f,block);rd(f,o.bitsPerSample);f.seekg(static_cast<std::streamoff>(n)-16,std::ios::cur);}else if(std::string(id,4)=="data"){o.dataBytes=n;f.seekg(n,std::ios::cur);}else f.seekg(n,std::ios::cur);if(o.sampleRate&&o.dataBytes)break;}return o.sampleRate!=0;}}
